import { parseAmount, convert, normalizeQuotes, normalizeHistory } from './finance.js';
const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
const iconPaths = {grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',chart:'<path d="M3 3v18h18M7 15l4-5 4 3 6-8"/>',exchange:'<path d="M4 7h16l-4-4M20 17H4l4 4M20 7l-4 4M4 17l4-4"/>',news:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M7 7h4v5H7zM15 7h2M15 11h2M7 16h10"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 11h18M8 15h2M14 15h2"/>',star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9Z"/>',globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v.2"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1.5 1.5M17.5 17.5 19 19M5 19l1.5-1.5M17.5 6.5 19 5"/>',moon:'<path d="M20.7 13A9 9 0 0 1 11 3.3 9 9 0 1 0 20.7 13Z"/>',refresh:'<path d="M20 8a8 8 0 0 0-14-3L3 8M3 3v5h5M4 16a8 8 0 0 0 14 3l3-3M21 21v-5h-5"/>'};
const icon = name => `<svg class="icon" aria-hidden="true" viewBox="0 0 24 24">${iconPaths[name] || iconPaths.info}</svg>`;
$$('[data-icon]').forEach(e => e.innerHTML = icon(e.dataset.icon));
const storage = { get(k, fallback) { try { const raw = localStorage.getItem(k); return raw ? JSON.parse(raw) : fallback; } catch { return fallback; } }, set(k,v) { try { localStorage.setItem(k,JSON.stringify(v)); } catch {} } };
const names = { USD:'Dólar americano', EUR:'Euro', BRL:'Real brasileiro', GBP:'Libra esterlina' };
const signs = {USD:'$',EUR:'€',BRL:'R$',GBP:'£'};
const state = { theme: storage.get('fw-theme','dark'), favorites: storage.get('fw-favorites',[]), quotes:null, source:null, history:[], code:'USD', days:30, page:'overview', region:'all', refreshing:false, historyRequest:0, cache:new Map(), widgetTheme:null };
if(!['dark','light'].includes(state.theme)) state.theme='dark';
if(!Array.isArray(state.favorites)) state.favorites=[];
state.favorites=state.favorites.filter(x=>names[x]);
const number = (value,digits=2) => Number(value).toLocaleString('pt-BR',{minimumFractionDigits:digits,maximumFractionDigits:digits});
const date = time => new Date(time).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});
const percent = n => `${n >= 0 ? '↗ +' : '↘ '}${number(n)}%`;
function toast(message) { $('#toast').textContent=message; $('#toast').classList.add('visible'); clearTimeout(toast.timer); toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3000); }
function applyTheme() { document.documentElement.dataset.theme=state.theme; $('#theme-toggle').innerHTML=icon(state.theme==='dark'?'sun':'moon'); $('#theme-toggle').setAttribute('aria-label',`Ativar modo ${state.theme==='dark'?'claro':'escuro'}`); $('meta[name="theme-color"]').content=state.theme==='dark'?'#0b1018':'#f6f5f0'; }
applyTheme();
$('#theme-toggle').addEventListener('click',()=>{state.theme=state.theme==='dark'?'light':'dark';storage.set('fw-theme',state.theme);applyTheme();renderChart();mountVisibleWidgets(true);});
function card(code) {
 const q=state.quotes?.[code]; const favorite=state.favorites.includes(code);
 return `<article class="quote-card"><div class="quote-card-top"><span class="currency-symbol currency-${code.toLowerCase()}">${signs[code]}</span><div><div class="currency-name">${names[code]}</div><div class="currency-code">${code} / ${code==='BRL'?'USD':'BRL'}</div></div><button class="icon-button favorite ${favorite?'is-favorite':''}" data-favorite="${code}" aria-label="${favorite?'Remover':'Adicionar'} ${names[code]} ${favorite?'dos':'aos'} favoritos" aria-pressed="${favorite}">${icon('star')}</button></div><div class="quote-price"><span class="price-prefix">${code==='BRL'?'US$':'R$'}</span>${q?number(q.rate,4):'—'}</div><div class="quote-bottom"><span class="change ${q?.change<0?'negative':''}">${q?.change!=null?percent(q.change):'—'}</span><span>${state.source==='Frankfurter'?'Referência diária':'variação do provedor'}</span></div><div class="quote-time">${q?'Cotação de '+date(q.time)+' · BRT':'Aguardando fonte de dados'}</div></article>`;
}
function renderQuotes() {
 $('#quote-grid').innerHTML=['USD','EUR','BRL','GBP'].map(card).join('');
 $('#fav-count').textContent=state.favorites.length;
 $('#favorites-list').innerHTML=state.favorites.length?`<div class="quote-grid">${state.favorites.map(card).join('')}</div>`:`<div class="empty-state">${icon('star')}Seu radar começa com uma escolha.<br><br>Toque na estrela de uma moeda para acompanhá-la aqui.<br><br><a class="text-link" href="#currencies">Explorar moedas ↗</a></div>`;
 const favorite=state.favorites.includes(state.code); $('#favorite-chart').classList.toggle('is-favorite',favorite); $('#favorite-chart').setAttribute('aria-pressed',String(favorite)); $('#favorite-chart').setAttribute('aria-label',`${favorite?'Remover':'Favoritar'} ${names[state.code]}`);
 const q=state.quotes?.[state.code]; $('#chart-value').textContent=q?'R$ '+number(q.rate,4):'—'; $('#chart-change').textContent=q?.change!=null?percent(q.change):''; $('#chart-change').classList.toggle('negative',q?.change<0);
}
function toggleFavorite(code) { state.favorites=state.favorites.includes(code)?state.favorites.filter(x=>x!==code):[...state.favorites,code]; storage.set('fw-favorites',state.favorites);renderQuotes();toast(state.favorites.includes(code)?`${names[code]} adicionado aos favoritos`:`${names[code]} removido dos favoritos`); }
document.addEventListener('click',e=>{const b=e.target.closest('[data-favorite]');if(b)toggleFavorite(b.dataset.favorite);});
$('#favorite-chart').addEventListener('click',()=>toggleFavorite(state.code));
async function getJSON(url) { const response=await fetch(url,{signal:AbortSignal.timeout(10000)}); if(!response.ok)throw new Error('Fonte indisponível');return response.json(); }
async function refreshQuotes(manual=false) {
 if(state.refreshing)return;state.refreshing=true;$('#refresh').disabled=true;
 try {
  try {const data=await getJSON('https://economia.awesomeapi.com.br/json/last/USD-BRL,EUR-BRL,GBP-BRL');state.quotes=normalizeQuotes(data);state.source='AwesomeAPI';}
  catch {
   const data=await getJSON('https://api.frankfurter.dev/v2/rates?base=BRL&quotes=USD,EUR,GBP'); const quotes={};
   for(const code of ['USD','EUR','GBP']) {const row=data.find(r=>r.quote===code);if(!row||!(row.rate>0))throw new Error('Taxas indisponíveis');quotes[code]={rate:1/row.rate,change:null,time:new Date(row.date+'T12:00:00Z').getTime()};}
   quotes.BRL={rate:1/quotes.USD.rate,change:null,time:quotes.USD.time};state.quotes=quotes;state.source='Frankfurter';
  }
  $('#connection-dot').style.background='var(--green)';$('#connection-status').textContent=state.source==='Frankfurter'?'Referência diária · Frankfurter (fonte alternativa)':`Cotações consultadas às ${new Date().toLocaleTimeString('pt-BR',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit'})} · BRT`;
  if(manual)toast('Consulta concluída. Confira o horário de cada cotação.');
 } catch {
  $('#connection-dot').style.background='var(--red)';$('#connection-status').textContent=state.quotes?'Sem conexão · mantendo a última cotação recebida':'Cotações indisponíveis · tente atualizar novamente'; if(manual)toast('Não foi possível atualizar. Tente novamente.');
 } finally {state.refreshing=false;$('#refresh').disabled=false;renderQuotes();renderConversion();}
}
function rates(){return state.quotes?{BRL:1,USD:state.quotes.USD.rate,EUR:state.quotes.EUR.rate,GBP:state.quotes.GBP.rate}:{BRL:1};}
function renderConversion() {
 const amount=parseAmount($('#amount').value); const from=$('#from').value,to=$('#to').value;
 const value=convert(amount,from,to,rates());$('#converted').textContent=value===null?'—':number(value);
 $('#conversion-error').textContent=Number.isNaN(amount)?'Digite um valor válido, como 1.000,00 (até 1 trilhão).':'';
 const rate=convert(1,from,to,rates());$('#conversion-rate').textContent=rate===null?'Aguardando uma cotação válida…':`1 ${from} = ${number(rate,4)} ${to}${from===to?'':` · ${state.source}`}`;
}
$('#amount').addEventListener('input',renderConversion);['from','to'].forEach(id=>$('#'+id).addEventListener('change',renderConversion));
$('#swap').addEventListener('click',()=>{const from=$('#from').value;$('#from').value=$('#to').value;$('#to').value=from;renderConversion();});
$('#converter-form').addEventListener('submit',e=>{e.preventDefault();renderConversion();if($('#conversion-error').textContent){$('#amount').focus();return;}if($('#converted').textContent==='—'){toast('Aguarde uma cotação válida para converter.');return;}toast(`Conversão calculada em ${$('#to').value}`);});
async function loadHistory(force=false) {
 $('#chart-wrap').onpointermove=null;$('#chart-wrap').onpointerleave=null;
 const request=++state.historyRequest,key=state.code+state.days;
 $('#chart-title').textContent=names[state.code];renderQuotes();state.history=[];$('#chart-wrap').innerHTML='<div class="chart-message">Carregando histórico de cotações…</div>';
 try {let history=state.cache.get(key); if(!history||force){history=normalizeHistory(await getJSON(`https://economia.awesomeapi.com.br/json/daily/${state.code}-BRL/${state.days}`));state.cache.set(key,history);}if(request!==state.historyRequest)return;state.history=history;$('#chart-source').textContent=`${history.length} observações diárias · AwesomeAPI`;renderChart();}
 catch {if(request!==state.historyRequest)return;$('#chart-wrap').innerHTML='<div class="chart-message">Histórico temporariamente indisponível.<br>Use “Atualizar dados” para tentar novamente.</div>';$('#chart-source').textContent='Histórico indisponível';}
}
function renderChart(){
 const data=state.history;if(data.length<2)return; const w=750,h=230,pad={l:12,r:62,t:20,b:31};const values=data.map(d=>d.value);const lo=Math.min(...values),hi=Math.max(...values),spread=(hi-lo)||hi*.01;const min=lo-spread*.18,max=hi+spread*.18;
 const x=i=>pad.l+i/(data.length-1)*(w-pad.l-pad.r),y=v=>pad.t+(max-v)/(max-min)*(h-pad.t-pad.b);
 const path=data.map((d,i)=>`${i?'L':'M'} ${x(i).toFixed(2)} ${y(d.value).toFixed(2)}`).join(' ');let grid='';
 for(let i=0;i<4;i++){const value=min+(max-min)*i/3;grid+=`<line x1="${pad.l}" x2="${w-pad.r}" y1="${y(value)}" y2="${y(value)}" stroke="var(--border)" stroke-dasharray="3 5"/><text x="${w-pad.r+12}" y="${y(value)+4}" fill="var(--muted)" font-size="10">${number(value,3)}</text>`;}
 for(let i=0;i<5;i++){const idx=Math.round(i*(data.length-1)/4);grid+=`<text x="${x(idx)}" y="${h-6}" text-anchor="${i===0?'start':i===4?'end':'middle'}" fill="var(--muted)" font-size="10">${new Date(data[idx].time).toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo',day:'2-digit',month:'short'})}</text>`;}
 const last=data.at(-1);$('#chart-wrap').innerHTML=`<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img" aria-label="Histórico de ${names[state.code]}: ${data.length} observações, de R$ ${number(data[0].value,4)} a R$ ${number(last.value,4)}"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="var(--accent)" stop-opacity=".2"/><stop offset="100%" stop-color="var(--accent)" stop-opacity="0"/></linearGradient></defs>${grid}<path d="${path} L ${x(data.length-1)} ${h-pad.b} L ${x(0)} ${h-pad.b} Z" fill="url(#chart-fill)"/><path d="${path}" fill="none" stroke="var(--accent)" stroke-width="2.2" vector-effect="non-scaling-stroke" stroke-linecap="round" stroke-linejoin="round"/><circle cx="${x(data.length-1)}" cy="${y(last.value)}" r="4" fill="var(--accent)"/><line id="crosshair" x1="0" x2="0" y1="${pad.t}" y2="${h-pad.b}" stroke="var(--muted)" stroke-dasharray="3 4" visibility="hidden"/></svg><div class="chart-tooltip" hidden></div>`;
 const wrap=$('#chart-wrap');wrap.onpointermove=e=>{const rect=wrap.getBoundingClientRect(),pos=(e.clientX-rect.left)/rect.width*w;const i=Math.max(0,Math.min(data.length-1,Math.round((pos-pad.l)/(w-pad.l-pad.r)*(data.length-1))));const d=data[i];const tooltip=wrap.querySelector('.chart-tooltip');tooltip.hidden=false;tooltip.textContent=`${date(d.time)} · R$ ${number(d.value,4)}`;const cross=$('#crosshair');cross.setAttribute('x1',x(i));cross.setAttribute('x2',x(i));cross.setAttribute('visibility','visible');};wrap.onpointerleave=()=>{wrap.querySelector('.chart-tooltip').hidden=true;$('#crosshair').setAttribute('visibility','hidden');};
}
$('#chart-currency').addEventListener('change',e=>{state.code=e.target.value;loadHistory();});
$$('[data-days]').forEach(b=>b.addEventListener('click',()=>{state.days=Number(b.dataset.days);$$('[data-days]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});loadHistory();}));
$('#refresh').addEventListener('click',()=>{refreshQuotes(true);loadHistory(true);});
const regions=[{id:'br',name:'Brasil',sub:'B3 · Bolsa de Valores Brasileira',flag:'🇧🇷',url:'https://www.tradingview.com/markets/stocks-brazil/',symbols:[{s:'BMFBOVESPA:IBOV',d:'Ibovespa'},{s:'BMFBOVESPA:PETR4',d:'Petrobras PN'},{s:'BMFBOVESPA:VALE3',d:'Vale ON'}]},{id:'us',name:'Estados Unidos',sub:'Wall Street · Principais índices',flag:'🇺🇸',url:'https://www.tradingview.com/markets/indices/',symbols:[{s:'FOREXCOM:SPXUSD',d:'S&P 500 · CFD'},{s:'FOREXCOM:NSXUSD',d:'Nasdaq 100 · CFD'},{s:'FOREXCOM:DJI',d:'Dow Jones · CFD'}]},{id:'eu',name:'Europa',sub:'Frankfurt, Londres e Paris',flag:'🇪🇺',url:'https://www.tradingview.com/markets/indices/',symbols:[{s:'INDEX:DEU40',d:'DAX · Alemanha'},{s:'FOREXCOM:UKXGBP',d:'FTSE 100 · CFD'},{s:'INDEX:CAC40',d:'CAC 40 · França'}]}];
function widget(id,type,config,link){
 const host=$('#'+id);if(!host)return;const signature=JSON.stringify([type,config]);if(host.dataset.signature===signature)return;host.dataset.signature=signature;
 host.innerHTML='<div class="tradingview-widget-container"><div class="tradingview-widget-container__widget"></div><div class="tradingview-widget-copyright"><a target="_blank" rel="noopener noreferrer" href="https://www.tradingview.com/">Dados por TradingView</a></div></div>';
 const wrapper=host.firstElementChild;const script=document.createElement('script');script.type='text/javascript';script.src=`https://s3.tradingview.com/external-embedding/embed-widget-${type}.js`;script.async=true;script.textContent=JSON.stringify(config);const fallback=()=>{if(!host.isConnected||host.dataset.signature!==signature)return;host.innerHTML=`<div class="widget-fallback"><span>Este painel não pôde ser carregado.</span><a href="${link}" target="_blank" rel="noopener noreferrer">Acompanhar na fonte ↗</a><button class="text-link" data-retry-widget="${id}">Tentar novamente</button></div>`;delete host.dataset.signature;};script.onerror=fallback;wrapper.appendChild(script);
 setTimeout(()=>{if(host.dataset.signature===signature&&!host.querySelector('iframe'))fallback();},18000);
}
function renderMarkets(){ $('#market-grid').innerHTML=regions.filter(r=>state.region==='all'||state.region===r.id).map(r=>`<article class="market-card"><div class="market-card-head"><span class="market-flag" aria-hidden="true">${r.flag}</span><div><h3>${r.name}</h3><small>${r.sub}</small></div><a href="${r.url}" target="_blank" rel="noopener noreferrer" aria-label="Abrir mercado ${r.name} no TradingView">↗</a></div><div class="widget-container market-widget" id="market-${r.id}"></div></article>`).join(''); }
function mountVisibleWidgets(force=false){
 if(force)$$('.widget-container').forEach(e=>delete e.dataset.signature);
 if(['overview','markets'].includes(state.page))regions.filter(r=>state.region==='all'||state.region===r.id).forEach(r=>widget('market-'+r.id,'market-overview',{colorTheme:state.theme,dateRange:'1M',locale:'br',isTransparent:true,showChart:false,showSymbolLogo:true,showFloatingTooltip:true,width:'100%',height:'100%',tabs:[{title:'Índices e ativos',symbols:r.symbols}]},r.url));
 if(['overview','news'].includes(state.page))widget('news-widget','timeline',{feedMode:'all_symbols',isTransparent:true,displayMode:'regular',width:'100%',height:'100%',colorTheme:state.theme,locale:'br'},'https://www.tradingview.com/news/');
 if(['overview','calendar'].includes(state.page))widget('calendar-widget','events',{colorTheme:state.theme,isTransparent:true,width:'100%',height:'100%',locale:'br',countryFilter:'br,us,de,fr,gb'},'https://www.tradingview.com/economic-calendar/');
}
document.addEventListener('click',e=>{if(e.target.closest('[data-retry-widget]'))mountVisibleWidgets();});
$$('[data-region]').forEach(b=>b.addEventListener('click',()=>{state.region=b.dataset.region;$$('[data-region]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});renderMarkets();mountVisibleWidgets();}));
const pages={overview:['Visão geral','O mercado, em perspectiva','Acompanhe o que importa. Conecte os pontos. Vá além.'],markets:['Mercados globais','Um mundo de possibilidades','Brasil, Estados Unidos e Europa. Acompanhe os principais movimentos.'],currencies:['Moedas e câmbio','O valor de cada movimento','Compare moedas, explore o histórico e faça sua conversão.'],news:['Notícias','O que move os mercados','Acompanhe as últimas notícias diretamente do TradingView.'],calendar:['Agenda econômica','Os próximos movimentos','Indicadores, decisões e divulgações para colocar no seu radar.'],favorites:['Meus favoritos','Seu mercado, de perto','As moedas que importam para você, em um só lugar.']};
function navigate(){const key=location.hash.slice(1);state.page=pages[key]?key:'overview';const p=pages[state.page];$('#breadcrumb-current').textContent=p[0];$('#page-title').innerHTML=p[1]+'<span>.</span>';$('#page-subtitle').textContent=p[2];document.title=p[0]+' | FinanceWEB';$$('[data-page]').forEach(a=>{a.classList.toggle('active',a.dataset.page===state.page);if(a.dataset.page===state.page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$$('[data-views]').forEach(e=>e.hidden=!e.dataset.views.split(' ').includes(state.page));$('#news-panel').hidden=state.page==='calendar';$('#calendar-panel').hidden=state.page==='news';$('.editorial-grid').style.gridTemplateColumns=['news','calendar'].includes(state.page)?'1fr':'';mountVisibleWidgets();window.scrollTo({top:0,behavior:'instant'});}
window.addEventListener('hashchange',navigate);
$('.skip-link').addEventListener('click',e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView();});
function sources(){ $('#info-title').textContent='Fontes e transparência';$('#info-content').innerHTML=`<p>Informação útil também precisa de contexto. Veja como os dados chegam até aqui.</p><h3>Câmbio · AwesomeAPI</h3><p>O portal consulta a <a href="https://docs.awesomeapi.com.br/api-de-moedas" target="_blank" rel="noopener noreferrer">AwesomeAPI</a> a cada 60 segundos enquanto esta aba está visível. Sem chave, a fonte pode usar cache. Cada cartão mostra o horário da cotação recebido do provedor, no fuso de Brasília. Fins de semana e feriados podem manter valores anteriores.</p><h3>Fonte alternativa · Frankfurter</h3><p>Se a fonte principal falhar, usamos as <a href="https://frankfurter.dev/" target="_blank" rel="noopener noreferrer">taxas diárias do Frankfurter</a>. Nesse caso, o painel identifica “referência diária”, sem variação intradiária. Não são cotações em tempo real.</p><h3>Bolsas, notícias e agenda · TradingView</h3><p>Os painéis incorporados atualizam conforme o provedor. Alguns mercados podem ter atraso, limitações de licença ou indisponibilidade. Consulte a <a href="https://www.tradingview.com/widget-docs/faq/data/" target="_blank" rel="noopener noreferrer">política de dados do TradingView</a>. Instrumentos identificados como CFD são referências derivadas do índice.</p><h3>Conversão de moedas</h3><p>Usamos a cotação de compra (bid) para calcular as taxas cruzadas. O real é mostrado também em dólares. Os resultados são indicativos e não incluem IOF, spread ou taxas de uma instituição financeira.</p><h3>Seus dados</h3><p>Tema e favoritos ficam salvos somente neste navegador. Não há cadastro nem execução de operações. Os painéis externos se conectam aos serviços dos respectivos provedores.</p>`;$('#info-dialog').showModal(); }
['source-button','data-info','footer-sources'].forEach(id=>$('#'+id).addEventListener('click',sources));
$('#learn-button').addEventListener('click',()=>{$('#info-title').textContent='Entenda os indicadores';$('#info-content').innerHTML='<h3>Câmbio</h3><p>O par USD/BRL mostra quantos reais equivalem a um dólar. Uma alta nesse par representa um dólar mais caro em reais. No par BRL/USD, a relação é inversa.</p><h3>Índices de bolsa</h3><p>Ibovespa, S&P 500, Nasdaq 100, DAX e FTSE 100 resumem o desempenho de grupos de ações. Cada índice tem critérios e composição próprios; os valores em pontos não devem ser comparados diretamente entre índices.</p><h3>Variação e histórico</h3><p>A porcentagem nos cartões é a variação informada pelo provedor. O gráfico mostra observações diárias, não cada negociação. Uma alta passada não garante retornos futuros.</p><h3>Agenda econômica</h3><p>Divulgações de inflação, juros e emprego podem afetar preços e expectativas. Observe o período de referência e a diferença entre o resultado divulgado e o esperado.</p><h3>Fontes oficiais para aprofundar</h3><p><a href="https://www.b3.com.br/pt_br/" target="_blank" rel="noopener noreferrer">B3</a> · <a href="https://www.bcb.gov.br/" target="_blank" rel="noopener noreferrer">Banco Central do Brasil</a> · <a href="https://www.investor.gov/" target="_blank" rel="noopener noreferrer">Investor.gov</a></p>';$('#info-dialog').showModal();});
$$('[data-close]').forEach(b=>b.addEventListener('click',()=>$('#'+b.dataset.close).close()));$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
const searchItems=[...Object.entries(names).map(([code,name])=>({name,code,page:'currencies'})),{name:'Ibovespa',code:'IBOV · Brasil',page:'markets',region:'br'},{name:'S&P 500',code:'SPX · Estados Unidos',page:'markets',region:'us'},{name:'Nasdaq 100',code:'NDX · Estados Unidos',page:'markets',region:'us'},{name:'Dow Jones',code:'DJI · Estados Unidos',page:'markets',region:'us'},{name:'DAX',code:'Alemanha · Europa',page:'markets',region:'eu'},{name:'FTSE 100',code:'Reino Unido · Europa',page:'markets',region:'eu'},{name:'CAC 40',code:'França · Europa',page:'markets',region:'eu'},{name:'Meus favoritos',code:'Sua lista de moedas',page:'favorites'}];
const clean=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function renderSearch(){const q=clean($('#search-input').value);const found=searchItems.filter(i=>clean(i.name+' '+i.code).includes(q));$('#search-results').innerHTML=found.length?found.map(i=>`<button class="search-result" data-search="${searchItems.indexOf(i)}">${icon(i.page==='currencies'?'exchange':i.page==='favorites'?'star':'chart')}<span>${i.name}<small>${i.code}</small></span><span>↗</span></button>`).join(''):'<div class="empty-state">Nenhum ativo encontrado. Tente dólar, Ibovespa ou DAX.</div>';}
function openSearch(){$('#search-input').value='';renderSearch();$('#search-dialog').showModal();$('#search-input').focus();}
$('#search-open').addEventListener('click',openSearch);$('#search-input').addEventListener('input',renderSearch);
$('#search-results').addEventListener('click',e=>{const b=e.target.closest('[data-search]');if(!b)return;const item=searchItems[Number(b.dataset.search)];$('#search-dialog').close();if(item.region){state.region=item.region;$$('[data-region]').forEach(x=>{x.classList.toggle('active',x.dataset.region===item.region);x.setAttribute('aria-pressed',String(x.dataset.region===item.region));});renderMarkets();}if(names[item.code]&&item.code!=='BRL'){state.code=item.code;$('#chart-currency').value=item.code;loadHistory();}location.hash=item.page;navigate();});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('dialog[open]')){e.preventDefault();openSearch();}});
$('#today').textContent=new Date().toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo',weekday:'long',day:'numeric',month:'long',year:'numeric'});$('#year').textContent=new Date().getFullYear();
renderQuotes();renderMarkets();navigate();refreshQuotes();loadHistory();
setInterval(()=>{if(!document.hidden)refreshQuotes();},60000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshQuotes();});
window.addEventListener('online',()=>refreshQuotes());window.addEventListener('offline',()=>{$('#connection-status').textContent='Sem conexão · última cotação recebida';$('#connection-dot').style.background='var(--red)';});
